/**
 * In-Memory User Store
 *
 * Demonstrates secure password credential storage:
 * - Plaintext passwords are NEVER persisted or stored.
 * - Only the Modular Crypt Format (MCF) hash generated by ArgonCore is stored.
 * - Volatile demonstration storage for local integration and testing purposes.
 */

class UserStore {
  constructor() {
    this.users = new Map();
  }

  /**
   * Creates and stores a new user record.
   * @param {string} username - User handle
   * @param {string} passwordHash - Encoded Argon2id MCF string
   * @param {Object} [meta={}] - Optional metadata
   * @returns {Object} Safe user representation
   */
  createUser(username, passwordHash, meta = {}) {
    const normalized = username.trim().toLowerCase();
    if (this.users.has(normalized)) {
      throw new Error(`Username '${username}' is already registered.`);
    }

    const record = {
      username: username.trim(),
      normalized,
      passwordHash,
      profileUsed: meta.profileUsed || 'custom',
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      lastLoginAt: null,
      rehashCount: 0
    };

    this.users.set(normalized, record);
    return this.sanitize(record);
  }

  /**
   * Finds a user by username (case-insensitive lookup).
   * @param {string} username
   * @returns {Object|null} Internal record including passwordHash
   */
  findByUsername(username) {
    if (!username) return null;
    const normalized = username.trim().toLowerCase();
    return this.users.get(normalized) || null;
  }

  /**
   * Updates a user's password hash (e.g. after a transparent rehash).
   * @param {string} username
   * @param {string} newPasswordHash
   * @returns {Object} Safe user representation
   */
  updatePasswordHash(username, newPasswordHash) {
    const user = this.findByUsername(username);
    if (!user) {
      throw new Error(`User '${username}' not found.`);
    }

    user.passwordHash = newPasswordHash;
    user.updatedAt = new Date().toISOString();
    user.rehashCount += 1;
    return this.sanitize(user);
  }

  /**
   * Records a successful login timestamp.
   * @param {string} username
   */
  recordLogin(username) {
    const user = this.findByUsername(username);
    if (user) {
      user.lastLoginAt = new Date().toISOString();
    }
  }

  /**
   * Returns all users in safe format without exposing sensitive details.
   * @returns {Array<Object>}
   */
  getAllUsers() {
    return Array.from(this.users.values()).map(user => this.sanitize(user));
  }

  /**
   * Checks if a username exists.
   * @param {string} username
   * @returns {boolean}
   */
  hasUser(username) {
    if (!username) return false;
    return this.users.has(username.trim().toLowerCase());
  }

  /**
   * Sanitizes a user record for API exposure.
   * Contains parsed parameter metadata and the hash string for demo inspection.
   * Plaintext passwords NEVER exist on the record.
   */
  sanitize(record) {
    const parsed = this.parseHashMetadata(record.passwordHash);
    return {
      username: record.username,
      createdAt: record.createdAt,
      updatedAt: record.updatedAt,
      lastLoginAt: record.lastLoginAt,
      rehashCount: record.rehashCount,
      profileUsed: record.profileUsed,
      hash: record.passwordHash,
      hashDetails: parsed
    };
  }

  /**
   * Parses basic MCF parameter metadata for UI display.
   * @param {string} encodedHash
   * @returns {Object}
   */
  parseHashMetadata(encodedHash) {
    if (!encodedHash || typeof encodedHash !== 'string') return {};
    const parts = encodedHash.split('$');
    // Format: $argon2id$v=19$m=1024,t=1,p=1$salt$hash
    if (parts.length >= 6) {
      const type = parts[1];
      const versionStr = parts[2];
      const paramsStr = parts[3];
      const salt = parts[4];
      const digest = parts[5];

      const params = {};
      paramsStr.split(',').forEach(pair => {
        const [k, v] = pair.split('=');
        if (k && v) params[k] = parseInt(v, 10);
      });

      return {
        type,
        version: versionStr.replace('v=', ''),
        memoryCost: params.m,
        timeCost: params.t,
        parallelism: params.p,
        saltPreview: salt.substring(0, 10) + '...',
        digestPreview: digest.substring(0, 12) + '...'
      };
    }
    return {};
  }

  /**
   * Resets the store.
   */
  clear() {
    this.users.clear();
  }
}

export const userStore = new UserStore();
